corpus_block("test-geom-ribbon.R: geom_ribbon() checks the aesthetics", {
  huron <- data.frame(year = 1875:1972, level = as.vector(LakeHuron))
  .plot("test-geom-ribbon.R: geom_ribbon() checks the aesthetics #1", p <- ggplot(huron) +
      geom_ribbon(aes(year, ymin = level - 5, ymax = level + 5), orientation = "y"))
  .plot("test-geom-ribbon.R: geom_ribbon() checks the aesthetics #2", p <- ggplot(huron) +
      geom_ribbon(aes(y = year, xmin = level - 5, xmax = level + 5), orientation = "x"))
  .plot("test-geom-ribbon.R: geom_ribbon() checks the aesthetics #3", p <- ggplot(huron) +
      geom_ribbon(aes(year, ymin = level - 5, ymax = level + 5, linewidth = year)))
})

corpus_block("test-geom-ribbon.R: NAs are dropped from the data", {
  df <- data_frame(x = 1:5, y = c(1, 1, NA, 1, 1))
  .plot("test-geom-ribbon.R: NAs are dropped from the data #1", p <- ggplot(df, aes(x))+
      geom_ribbon(aes(ymin = y - 1, ymax = y + 1)))
  p <- ggplot_build(p)
})

corpus_block("test-geom-ribbon.R: geom_ribbon works in both directions", {
  dat <- data_frame(x = seq_len(5),
                      ymin = c(1, 2, 1.5, 1.8, 1),
                      ymax = c(4, 6, 5, 4.5, 5.2))
  .plot("test-geom-ribbon.R: geom_ribbon works in both directions #1", p <- ggplot(dat, aes(x, ymin = ymin, ymax = ymax)) + geom_ribbon())
  x <- get_layer_data(p)
  .plot("test-geom-ribbon.R: geom_ribbon works in both directions #2", p <- ggplot(dat, aes(y = x, xmin = ymin, xmax = ymax)) + geom_ribbon())
  y <- get_layer_data(p)
  x$flipped_aes <- NULL
  y$flipped_aes <- NULL
})

corpus_block("test-geom-ribbon.R: outline.type option works", {
  df <- data_frame(x = 1:4, y = c(1, 1, 1, 1))
  .plot("test-geom-ribbon.R: outline.type option works #1", p <- ggplot(df, aes(x, ymin = -y, ymax = y)))
  .plot("test-geom-ribbon.R: outline.type option works #2", p + geom_ribbon())
  g_ribbon_default <- get_layer_grob(p + geom_ribbon())[[1]]
  .plot("test-geom-ribbon.R: outline.type option works #3", p + geom_ribbon(outline.type = "upper"))
  g_ribbon_upper   <- get_layer_grob(p + geom_ribbon(outline.type = "upper"))[[1]]
  .plot("test-geom-ribbon.R: outline.type option works #4", p + geom_ribbon(outline.type = "lower"))
  g_ribbon_lower   <- get_layer_grob(p + geom_ribbon(outline.type = "lower"))[[1]]
  .plot("test-geom-ribbon.R: outline.type option works #5", p + geom_ribbon(outline.type = "full"))
  g_ribbon_full    <- get_layer_grob(p + geom_ribbon(outline.type = "full"))[[1]]
  .plot("test-geom-ribbon.R: outline.type option works #6", ggplot(df, aes(x, y)) + geom_area(stat = "identity"))
  g_area_default   <- get_layer_grob(ggplot(df, aes(x, y)) + geom_area(stat = "identity"))[[1]]
})

corpus_block("test-geom-ribbon.R: ribbons can have gradients", {
  skip_if_not(
      check_device("gradients", action = "test"),
      "graphics device does not support gradients."
    )
  df <- data.frame(x = 1:2, ymin = c(-1:-2), ymax = 1:2)
  .plot("test-geom-ribbon.R: ribbons can have gradients #1", p <- ggplot(df, aes(x, ymin = ymin, ymax = ymax, fill = x)) +
      geom_ribbon(outline.type = "full") +
      scale_fill_gradientn(colours = c("red", "blue")))
  fill <- get_layer_grob(p)[[1]]$children[[1]]$gp$fill
})

